  const hk_real d6 = (HK_LIT(2) * t5 * d5);
  const hk_real t7 = (t4 - t6);
  const hk_real d7 = (d4 - d6);
  const hk_real t8 = hk_sqrt(t7);
  const hk_real d8 = (d7 / (HK_LIT(2) * t8));
  const hk_real t9 = (t2 * t8);
  const hk_real d9 = (d2 * t8 + t2 * d8);
  const hk_real t10 = (t0 / t9);
  const hk_real d10 = ((d0 * t9 - t0 * d9) / (t9 * t9));
  const hk_real t11 = (t3 + t10);
  const hk_real d11 = (d3 + d10);
