  const hk_real d6 = (d1 + d4);
  const hk_real t7 = t5 * t5;
  const hk_real d7 = (HK_LIT(2) * t5 * d5);
  const hk_real t8 = t6 * t6;
  const hk_real d8 = (HK_LIT(2) * t6 * d6);
  const hk_real t9 = (t7 + t8);
